  const { Group, Mesh, PlaneGeometry, Vector3 } = THREE;

  // Root group
  const root = new Group();
  root.position.copy(new Vector3(0, 0, 0));
  root.rotation.order = 'XYZ';

  // ─────────────────────────────────────────────────────────────────────────
  // PANEL DIMENSIONS & LAYOUT
