  // Radial gradient: #14141a (center) -> #0b0b10 (edges)
  const gradientColor = mix(
    color('#14141a'),
    color('#0b0b10'),
    distFromCenter.clamp(0, 1)
  );

  // Grid pattern: hairline at 0.25-unit pitch in UV space
  const gridUV = uvNode.mul(vec2(panelW, panelH).mul(1.0 / gridPitch));
  const gridFract = gridUV.fract();
  const gridThreshold = 0.008 / gridPitch; // hairline thickness in normalized coords
  const gridLines = mix(
    1.0,
    0.0,
    gridFract.min().smoothstep(gridThreshold, gridThreshold + 0.001)
  );
  const gridAlpha = color('#e8ecf2').mul(gridOpacity).mul(gridLines);

  // Composite: gradient + grid overlay
  const panelColor = mix(gradientColor, color('#e8ecf2'), gridAlpha.a);

  const panelMaterial = new MeshBasicNodeMaterial({
    colorNode: panelColor,
  });

  const panelMesh = new Mesh(panelGeometry, panelMaterial);
